package uk.ac.ravensbourne.casevault.crypto; import com.google.crypto.tink.Aead; import com.google.crypto.tink.CleartextKeysetHandle; import com.google.crypto.tink.JsonKeysetReader; import com.google.crypto.tink.KeysetHandle; import com.google.crypto.tink.aead.AeadConfig; import com.google.crypto.tink.aead.AeadKeyTemplates; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.context.annotation.Profile;
@Configuration public class TinkKeysetConfiguration { @Bean @Profile("test") KeysetProvider testKeysetProvider() throws Exception { AeadConfig.register(); Aead a=KeysetHandle.generateNew(AeadKeyTemplates.AES256_GCM).getPrimitive(Aead.class); return ()->a;} @Bean @Profile("!test") KeysetProvider fileKeysetProvider(@Value("${casevault.evidence.tink-keyset-path:${TINK_KEYSET_PATH:}}") String path) throws Exception {if(path==null||path.isBlank())throw new IllegalStateException("TINK_KEYSET_PATH is required");AeadConfig.register();Aead a=CleartextKeysetHandle.read(JsonKeysetReader.withPath(path)).getPrimitive(Aead.class);return ()->a;} }
